# Sistema de Pedidos para Restaurante

=== README.md ===
# Sistema de Pedidos para Restaurante

Sistema completo de pedidos online para restaurantes com autenticação de usuários, gerenciamento de cardápio e acompanhamento de pedidos em tempo real.

## Requisitos

- Node.js 18 ou superior
- npm (gerenciador de pacotes do Node.js)

## Instalação

1. Instale o Node.js em https://nodejs.org/ (escolha a versão LTS)

2. Abra o terminal/prompt de comando na pasta do projeto

3. Instale as dependências:
```bash
npm install
```

## Executar o projeto

1. Inicie o servidor:
```bash
npm start
```

2. Abra o navegador e acesse:
```
http://localhost:3000
```

## Contas padrão

### Gerente
- Email: gerente@restaurante.com
- Senha: gerente123

### Cliente de teste
- Email: cliente@email.com
- Senha: cliente123

Você pode criar novas contas na tela de registro.

## Funcionalidades

### Para Clientes:
- Ver cardápio completo
- Fazer pedidos
- Acompanhar status dos pedidos
- Histórico de pedidos

### Para Gerente:
- Cadastrar, editar e remover pratos
- Ver todos os pedidos
- Alterar status dos pedidos (Pendente → Preparando → Pronto → Entregue)
- Gerenciar cardápio completo

## Tecnologias utilizadas

- Node.js + Express (backend)
- HTML/CSS/JavaScript (frontend)
- SQLite (banco de dados)
- Autenticação com sessões

=== package.json ===
{
  "name": "sistema-pedidos-restaurante",
  "version": "1.0.0",
  "description": "Sistema de pedidos online para restaurante",
  "main": "server.js",
  "scripts": {
    "start": "node server.js"
  },
  "keywords": ["restaurante", "pedidos", "nodejs"],
  "author": "",
  "license": "MIT",
  "dependencies": {
    "express": "^4.18.2",
    "express-session": "^1.17.3",
    "better-sqlite3": "^9.2.2",
    "bcrypt": "^5.1.1"
  }
}

=== server.js ===
const express = require('express');
const session = require('express-session');
const bcrypt = require('bcrypt');
const Database = require('better-sqlite3');
const path = require('path');

const app = express();
const db = new Database('restaurante.db');

// Configurações
app.use(express.json());
app.use(express.urlencoded({ extended: true }));
app.use(express.static('public'));
app.use(session({
  secret: 'restaurante-secret-key-muito-segura-2024',
  resave: false,
  saveUninitialized: false,
  cookie: { maxAge: 24 * 60 * 60 * 1000 } // 24 horas
}));

// Inicializar banco de dados
db.exec(`
  CREATE TABLE IF NOT EXISTS usuarios (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL,
    email TEXT UNIQUE NOT NULL,
    senha TEXT NOT NULL,
    tipo TEXT NOT NULL DEFAULT 'cliente',
    criado_em DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS pratos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    nome TEXT NOT NULL,
    descricao TEXT,
    preco REAL NOT NULL,
    categoria TEXT NOT NULL,
    imagem TEXT,
    disponivel INTEGER DEFAULT 1,
    criado_em DATETIME DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS pedidos (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    usuario_id INTEGER NOT NULL,
    total REAL NOT NULL,
    status TEXT DEFAULT 'Pendente',
    observacoes TEXT,
    criado_em DATETIME DEFAULT CURRENT_TIMESTAMP,
    FOREIGN KEY (usuario_id) REFERENCES usuarios(id)
  );

  CREATE TABLE IF NOT EXISTS itens_pedido (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    pedido_id INTEGER NOT NULL,
    prato_id INTEGER NOT NULL,
    quantidade INTEGER NOT NULL,
    preco_unitario REAL NOT NULL,
    FOREIGN KEY (pedido_id) REFERENCES pedidos(id),
    FOREIGN KEY (prato_id) REFERENCES pratos(id)
  );
`);

// Criar usuário gerente padrão se não existir
const gerente = db.prepare('SELECT * FROM usuarios WHERE email = ?').get('gerente@restaurante.com');
if (!gerente) {
  const senhaHash = bcrypt.hashSync('gerente123', 10);
  db.prepare('INSERT INTO usuarios (nome, email, senha, tipo) VALUES (?, ?, ?, ?)').run(
    'Gerente',
    'gerente@restaurante.com',
    senhaHash,
    'gerente'
  );
}

// Criar cliente de teste se não existir
const cliente = db.prepare('SELECT * FROM usuarios WHERE email = ?').get('cliente@email.com');
if (!cliente) {
  const senhaHash = bcrypt.hashSync('cliente123', 10);
  db.prepare('INSERT INTO usuarios (nome, email, senha, tipo) VALUES (?, ?, ?, ?)').run(
    'Cliente Teste',
    'cliente@email.com',
    senhaHash,
    'cliente'
  );
}

// Adicionar pratos de exemplo se não existirem
const pratosExistentes = db.prepare('SELECT COUNT(*) as count FROM pratos').get();
if (pratosExistentes.count === 0) {
  const inserirPrato = db.prepare('INSERT INTO pratos (nome, descricao, preco, categoria, disponivel) VALUES (?, ?, ?, ?, ?)');

  inserirPrato.run('Pizza Margherita', 'Molho de tomate, mussarela e manjericão', 35.00, 'Pizza', 1);
  inserirPrato.run('Pizza Calabresa', 'Molho de tomate, mussarela e calabresa', 38.00, 'Pizza', 1);
  inserirPrato.run('Hambúrguer Artesanal', 'Pão brioche, burger 180g, queijo, alface, tomate', 28.00, 'Lanche', 1);
  inserirPrato.run('Batata Frita', 'Porção de batata frita crocante', 15.00, 'Acompanhamento', 1);
  inserirPrato.run('Refrigerante Lata', 'Refrigerante 350ml', 5.00, 'Bebida', 1);
  inserirPrato.run('Suco Natural', 'Suco natural 500ml', 8.00, 'Bebida', 1);
  inserirPrato.run('Lasanha Bolonhesa', 'Lasanha de carne com molho bolonhesa', 32.00, 'Massa', 1);
  inserirPrato.run('Salada Caesar', 'Alface, frango grelhado, croutons e molho caesar', 22.00, 'Salada', 1);
}

// Middleware de autenticação
function autenticar(req, res, next) {
  if (req.session.usuarioId) {
    next();
  } else {
    res.status(401).json({ erro: 'Não autenticado' });
  }
}

function autenticarGerente(req, res, next) {
  if (req.session.usuarioId && req.session.usuarioTipo === 'gerente') {
    next();
  } else {
    res.status(403).json({ erro: 'Acesso negado' });
  }
}

// Rotas de autenticação
app.post('/api/registro', (req, res) => {
  try {
    const { nome, email, senha } = req.body;

    if (!nome || !email || !senha) {
      return res.status(400).json({ erro: 'Preencha todos os campos' });
    }

    const usuarioExistente = db.prepare('SELECT * FROM usuarios WHERE email = ?').get(email);
    if (usuarioExistente) {
      return res.status(400).json({ erro: 'Email já cadastrado' });
    }

    const senhaHash = bcrypt.hashSync(senha, 10);
    const resultado = db.prepare('INSERT INTO usuarios (nome, email, senha, tipo) VALUES (?, ?, ?, ?)').run(
      nome,
      email,
      senhaHash,
      'cliente'
    );

    req.session.usuarioId = resultado.lastInsertRowid;
    req.session.usuarioNome = nome;
    req.session.usuarioTipo = 'cliente';

    res.json({ sucesso: true, usuario: { id: resultado.lastInsertRowid, nome, tipo: 'cliente' } });
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao registrar usuário' });
  }
});

app.post('/api/login', (req, res) => {
  try {
    const { email, senha } = req.body;

    if (!email || !senha) {
      return res.status(400).json({ erro: 'Preencha todos os campos' });
    }

    const usuario = db.prepare('SELECT * FROM usuarios WHERE email = ?').get(email);
    if (!usuario) {
      return res.status(401).json({ erro: 'Email ou senha incorretos' });
    }

    const senhaCorreta = bcrypt.compareSync(senha, usuario.senha);
    if (!senhaCorreta) {
      return res.status(401).json({ erro: 'Email ou senha incorretos' });
    }

    req.session.usuarioId = usuario.id;
    req.session.usuarioNome = usuario.nome;
    req.session.usuarioTipo = usuario.tipo;

    res.json({ 
      sucesso: true, 
      usuario: { 
        id: usuario.id, 
        nome: usuario.nome, 
        tipo: usuario.tipo 
      } 
    });
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao fazer login' });
  }
});

app.post('/api/logout', (req, res) => {
  req.session.destroy();
  res.json({ sucesso: true });
});

app.get('/api/usuario-atual', autenticar, (req, res) => {
  const usuario = db.prepare('SELECT id, nome, email, tipo FROM usuarios WHERE id = ?').get(req.session.usuarioId);
  res.json(usuario);
});

// Rotas de pratos
app.get('/api/pratos', autenticar, (req, res) => {
  const pratos = db.prepare('SELECT * FROM pratos ORDER BY categoria, nome').all();
  res.json(pratos);
});

app.get('/api/pratos/:id', autenticar, (req, res) => {
  const prato = db.prepare('SELECT * FROM pratos WHERE id = ?').get(req.params.id);
  if (!prato) {
    return res.status(404).json({ erro: 'Prato não encontrado' });
  }
  res.json(prato);
});

app.post('/api/pratos', autenticarGerente, (req, res) => {
  try {
    const { nome, descricao, preco, categoria, disponivel } = req.body;

    if (!nome || !preco || !categoria) {
      return res.status(400).json({ erro: 'Preencha os campos obrigatórios' });
    }

    const resultado = db.prepare(
      'INSERT INTO pratos (nome, descricao, preco, categoria, disponivel) VALUES (?, ?, ?, ?, ?)'
    ).run(nome, descricao || '', preco, categoria, disponivel ? 1 : 0);

    const prato = db.prepare('SELECT * FROM pratos WHERE id = ?').get(resultado.lastInsertRowid);
    res.json(prato);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao criar prato' });
  }
});

app.put('/api/pratos/:id', autenticarGerente, (req, res) => {
  try {
    const { nome, descricao, preco, categoria, disponivel } = req.body;

    if (!nome || !preco || !categoria) {
      return res.status(400).json({ erro: 'Preencha os campos obrigatórios' });
    }

    db.prepare(
      'UPDATE pratos SET nome = ?, descricao = ?, preco = ?, categoria = ?, disponivel = ? WHERE id = ?'
    ).run(nome, descricao || '', preco, categoria, disponivel ? 1 : 0, req.params.id);

    const prato = db.prepare('SELECT * FROM pratos WHERE id = ?').get(req.params.id);
    res.json(prato);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao atualizar prato' });
  }
});

app.delete('/api/pratos/:id', autenticarGerente, (req, res) => {
  try {
    db.prepare('DELETE FROM pratos WHERE id = ?').run(req.params.id);
    res.json({ sucesso: true });
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao deletar prato' });
  }
});

// Rotas de pedidos
app.get('/api/pedidos', autenticar, (req, res) => {
  try {
    let pedidos;

    if (req.session.usuarioTipo === 'gerente') {
      // Gerente vê todos os pedidos
      pedidos = db.prepare(`
        SELECT p.*, u.nome as cliente_nome, u.email as cliente_email
        FROM pedidos p
        JOIN usuarios u ON p.usuario_id = u.id
        ORDER BY p.criado_em DESC
      `).all();
    } else {
      // Cliente vê apenas seus pedidos
      pedidos = db.prepare(`
        SELECT p.*, u.nome as cliente_nome
        FROM pedidos p
        JOIN usuarios u ON p.usuario_id = u.id
        WHERE p.usuario_id = ?
        ORDER BY p.criado_em DESC
      `).all(req.session.usuarioId);
    }

    // Buscar itens de cada pedido
    for (let pedido of pedidos) {
      pedido.itens = db.prepare(`
        SELECT ip.*, pr.nome as prato_nome
        FROM itens_pedido ip
        JOIN pratos pr ON ip.prato_id = pr.id
        WHERE ip.pedido_id = ?
      `).all(pedido.id);
    }

    res.json(pedidos);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao buscar pedidos' });
  }
});

app.get('/api/pedidos/:id', autenticar, (req, res) => {
  try {
    const pedido = db.prepare(`
      SELECT p.*, u.nome as cliente_nome, u.email as cliente_email
      FROM pedidos p
      JOIN usuarios u ON p.usuario_id = u.id
      WHERE p.id = ?
    `).get(req.params.id);

    if (!pedido) {
      return res.status(404).json({ erro: 'Pedido não encontrado' });
    }

    // Verificar permissão
    if (req.session.usuarioTipo !== 'gerente' && pedido.usuario_id !== req.session.usuarioId) {
      return res.status(403).json({ erro: 'Acesso negado' });
    }

    pedido.itens = db.prepare(`
      SELECT ip.*, pr.nome as prato_nome
      FROM itens_pedido ip
      JOIN pratos pr ON ip.prato_id = pr.id
      WHERE ip.pedido_id = ?
    `).all(pedido.id);

    res.json(pedido);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao buscar pedido' });
  }
});

app.post('/api/pedidos', autenticar, (req, res) => {
  try {
    const { itens, observacoes } = req.body;

    if (!itens || itens.length === 0) {
      return res.status(400).json({ erro: 'Pedido vazio' });
    }

    let total = 0;
    const itensValidados = [];

    // Validar itens e calcular total
    for (let item of itens) {
      const prato = db.prepare('SELECT * FROM pratos WHERE id = ? AND disponivel = 1').get(item.prato_id);
      if (!prato) {
        return res.status(400).json({ erro: `Prato ID ${item.prato_id} não disponível` });
      }

      itensValidados.push({
        prato_id: prato.id,
        quantidade: item.quantidade,
        preco_unitario: prato.preco
      });

      total += prato.preco * item.quantidade;
    }

    // Criar pedido
    const resultado = db.prepare(
      'INSERT INTO pedidos (usuario_id, total, status, observacoes) VALUES (?, ?, ?, ?)'
    ).run(req.session.usuarioId, total, 'Pendente', observacoes || '');

    const pedidoId = resultado.lastInsertRowid;

    // Adicionar itens do pedido
    const inserirItem = db.prepare(
      'INSERT INTO itens_pedido (pedido_id, prato_id, quantidade, preco_unitario) VALUES (?, ?, ?, ?)'
    );

    for (let item of itensValidados) {
      inserirItem.run(pedidoId, item.prato_id, item.quantidade, item.preco_unitario);
    }

    // Buscar pedido completo
    const pedido = db.prepare(`
      SELECT p.*, u.nome as cliente_nome
      FROM pedidos p
      JOIN usuarios u ON p.usuario_id = u.id
      WHERE p.id = ?
    `).get(pedidoId);

    pedido.itens = db.prepare(`
      SELECT ip.*, pr.nome as prato_nome
      FROM itens_pedido ip
      JOIN pratos pr ON ip.prato_id = pr.id
      WHERE ip.pedido_id = ?
    `).all(pedidoId);

    res.json(pedido);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao criar pedido' });
  }
});

app.put('/api/pedidos/:id/status', autenticarGerente, (req, res) => {
  try {
    const { status } = req.body;

    const statusPermitidos = ['Pendente', 'Preparando', 'Pronto', 'Entregue', 'Cancelado'];
    if (!statusPermitidos.includes(status)) {
      return res.status(400).json({ erro: 'Status inválido' });
    }

    db.prepare('UPDATE pedidos SET status = ? WHERE id = ?').run(status, req.params.id);

    const pedido = db.prepare(`
      SELECT p.*, u.nome as cliente_nome, u.email as cliente_email
      FROM pedidos p
      JOIN usuarios u ON p.usuario_id = u.id
      WHERE p.id = ?
    `).get(req.params.id);

    pedido.itens = db.prepare(`
      SELECT ip.*, pr.nome as prato_nome
      FROM itens_pedido ip
      JOIN pratos pr ON ip.prato_id = pr.id
      WHERE ip.pedido_id = ?
    `).all(req.params.id);

    res.json(pedido);
  } catch (erro) {
    res.status(500).json({ erro: 'Erro ao atualizar status' });
  }
});

// Rota para servir o HTML
app.get('*', (req, res) => {
  res.sendFile(path.join(__dirname, 'public', 'index.html'));
});

// Iniciar servidor
const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Servidor rodando em http://localhost:${PORT}`);
});

=== public/index.html ===
<!DOCTYPE html>
<html lang="pt-BR">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Sistema de Pedidos - Restaurante</title>
  <link rel="stylesheet" href="style.css">
</head>
<body>
  <div id="app">
    <!-- Tela de Login -->
    <div id="tela-login" class="tela">
      <div class="container-login">
        <div class="card-login">
          <h1>🍽️ Restaurante</h1>
          <h2>Sistema de Pedidos</h2>

          <div id="form-login" class="form-auth">
            <h3>Entrar</h3>
            <input type="email" id="login-email" placeholder="Email" required>
            <input type="password" id="login-senha" placeholder="Senha" required>
            <button onclick="fazerLogin()">Entrar</button>
            <p class="link-alternativo">
              Não tem conta? <a href="#" onclick="mostrarRegistro()">Registre-se</a>
            </p>
          </div>

          <div id="form-registro" class="form-auth" style="display: none;">
            <h3>Registrar</h3>
            <input type="text" id="registro-nome" placeholder="Nome completo" required>
            <input type="email" id="registro-email" placeholder="Email" required>
            <input type="password" id="registro-senha" placeholder="Senha" required>
            <button onclick="fazerRegistro()">Registrar</button>
            <p class="link-alternativo">
              Já tem conta? <a href="#" onclick="mostrarLogin()">Entrar</a>
            </p>
          </div>

          <div class="info-login">
            <h4>Contas de teste:</h4>
            <p><strong>Gerente:</strong> gerente@restaurante.com / gerente123</p>
            <p><strong>Cliente:</strong> cliente@email.com / cliente123</p>
          </div>
        </div>
      </div>
    </div>

    <!-- Tela Principal -->
    <div id="tela-principal" class="tela" style="display: none;">
      <header>
        <div class="header-content">
          <h1>🍽️ Restaurante</h1>
          <div class="user-info">
            <span id="nome-usuario"></span>
            <button onclick="fazerLogout()" class="btn-logout">Sair</button>
          </div>
        </div>
        <nav id="navegacao"></nav>
      </header>

      <main>
        <!-- Tela Cardápio (Cliente) -->
        <div id="secao-cardapio" class="secao">
          <div class="container">
            <h2>Cardápio</h2>
            <div id="carrinho-resumo" style="display: none;" class="carrinho-flutuante">
              <h3>Carrinho (<span id="carrinho-contador">0</span>)</h3>
              <button onclick="abrirCarrinho()" class="btn-primary">Ver Carrinho</button>
            </div>
            <div id="lista-cardapio" class="grid-pratos"></div>
          </div>
        </div>

        <!-- Modal do Carrinho -->
        <div id="modal-carrinho" class="modal" style="display: none;">
          <div class="modal-content">
            <span class="fechar" onclick="fecharCarrinho()">&times;</span>
            <h2>Seu Carrinho</h2>
            <div id="itens-carrinho"></div>
            <div class="total-carrinho">
              <h3>Total: R$ <span id="total-carrinho">0.00</span></h3>
            </div>
            <div class="form-group">
              <label>Observações (opcional):</label>
              <textarea id="observacoes-pedido" rows="3" placeholder="Ex: Sem cebola, ponto da carne, etc."></textarea>
            </div>
            <div class="acoes-carrinho">
              <button onclick="limparCarrinho()" class="btn-secondary">Limpar Carrinho</button>
              <button onclick="finalizarPedido()" class="btn-primary">Finalizar Pedido</button>
            </div>
          </div>
        </div>

        <!-- Tela Meus Pedidos (Cliente) -->
        <div id="secao-meus-pedidos" class="secao" style="display: none;">
          <div class="container">
            <h2>Meus Pedidos</h2>
            <div id="lista-meus-pedidos"></div>
          </div>
        </div>

        <!-- Tela Gerenciar Cardápio (Gerente) -->
        <div id="secao-gerenciar-cardapio" class="secao" style="display: none;">
          <div class="container">
            <div class="header-secao">
              <h2>Gerenciar Cardápio</h2>
              <button onclick="abrirModalPrato()" class="btn-primary">+ Adicionar Prato</button>
            </div>
            <div id="lista-gerenciar-cardapio"></div>
          </div>
        </div>

        <!-- Modal Adicionar/Editar Prato -->
        <div id="modal-prato" class="modal" style="display: none;">
          <div class="modal-content">
            <span class="fechar" onclick="fecharModalPrato()">&times;</span>
            <h2 id="modal-prato-titulo">Adicionar Prato</h2>
            <form id="form-prato" onsubmit="salvarPrato(event)">
              <input type="hidden" id="prato-id">
              <div class="form-group">
                <label>Nome do Prato *</label>
                <input type="text" id="prato-nome" required>
              </div>
              <div class="form-group">
                <label>Descrição</label>
                <textarea id="prato-descricao" rows="3"></textarea>
              </div>
              <div class="form-group">
                <label>Preço (R$) *</label>
                <input type="number" id="prato-preco" step="0.01" min="0" required>
              </div>
              <div class="form-group">
                <label>Categoria *</label>
                <select id="prato-categoria" required>
                  <option value="">Selecione...</option>
                  <option value="Entrada">Entrada</option>
                  <option value="Prato Principal">Prato Principal</option>
                  <option value="Pizza">Pizza</option>
                  <option value="Lanche">Lanche</option>
                  <option value="Massa">Massa</option>
                  <option value="Salada">Salada</option>
                  <option value="Acompanhamento">Acompanhamento</option>
                  <option value="Sobremesa">Sobremesa</option>
                  <option value="Bebida">Bebida</option>
                </select>
              </div>
              <div class="form-group">
                <label>
                  <input type="checkbox" id="prato-disponivel" checked>
                  Disponível para venda
                </label>
              </div>
              <div class="form-actions">
                <button type="button" onclick="fecharModalPrato()" class="btn-secondary">Cancelar</button>
                <button type="submit" class="btn-primary">Salvar</button>
              </div>
            </form>
          </div>
        </div>

        <!-- Tela Todos os Pedidos (Gerente) -->
        <div id="secao-todos-pedidos" class="secao" style="display: none;">
          <div class="container">
            <h2>Todos os Pedidos</h2>
