* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

:root {
  --primary: #e74c3c;
  --primary-dark: #c0392b;
  --secondary: #34495e;
  --success: #27ae60;
  --warning: #f39c12;
  --info: #3498db;
  --light: #ecf0f1;
  --dark: #2c3e50;
  --gray: #95a5a6;
}

body {
